import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

export interface PageSchemaBlock {
	schemaType: string;
	jsonLd: string;
}

interface PageSchemaApiResponse {
	code?: number;
	result?: PageSchemaBlock[];
}

// Module 10 redesign — reads the JSON-LD blocks the SEO agent has written live via
// update_page_schema (PageSchema collection, pixtar-api) instead of a hardcoded
// per-component literal, so a schema fix reaches the live, server-rendered site on
// the next request with no frontend deploy — same live-without-deploy behavior
// PageSeoService already gives meta_title/meta_description. Only ever returns
// "active" blocks for automation-allowlisted types (BreadcrumbList, WebSite,
// CollectionPage, AboutPage, Service); everything else stays hardcoded/manual.
@Injectable({
	providedIn: 'root'
})
export class PageSchemaService {
	private readonly endpoint = `${environment.baseUrl}/api/page/getpageschema`;

	constructor(
		private readonly http: HttpClient,
		private readonly transferState: TransferState,
		@Inject(PLATFORM_ID) private readonly platformId: Object
	) { }

	getPageSchema(pageName: string): Observable<PageSchemaBlock[]> {
		const stateKey = makeStateKey<PageSchemaBlock[]>(`page-schema:${pageName}`);

		if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
			const cached = this.transferState.get<PageSchemaBlock[]>(stateKey, []);
			this.transferState.remove(stateKey);
			return of(cached);
		}

		return this.http.post<PageSchemaApiResponse>(this.endpoint, { pageName }).pipe(
			map((response) => response?.result ?? []),
			tap((blocks) => {
				if (isPlatformServer(this.platformId)) {
					this.transferState.set(stateKey, blocks);
				}
			}),
			catchError((error) => {
				console.warn(`PageSchemaService: failed to load schema for "${pageName}"`, error?.error?.message ?? error?.message);
				return of([]);
			})
		);
	}
}
